1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  issueGraphLivenessAutoRecoveryRequestSchema,
5	  patchInstanceExperimentalSettingsSchema,
6	  patchInstanceGeneralSettingsSchema,
7	} from "@paperclipai/shared";
8	import { assertBoardOrgAccess, assertInstanceAdmin } from "./authz.js";
9	import { heartbeatService, instanceSettingsService, logActivity } from "../services/index.js";
10	import { expressHandler } from "../http/express-adapter.js";
11	import type { Handler } from "../http/types.js";
12	import type { StorageService } from "../storage/types.js";
13	
14	function buildHandlers(db: Db) {
15	  const svc = instanceSettingsService(db);
16	  const heartbeat = heartbeatService(db);
17	
18	  // server/src/routes/instance-settings.ts:28
19	  const getGeneralSettings: Handler = async (ctx) => {
20	    assertBoardOrgAccess(ctx);
21	    return Response.json(await svc.getGeneral());
22	  };
23	
24	  // server/src/routes/instance-settings.ts:35
25	  const patchGeneralSettings: Handler = async (ctx) => {
26	    assertInstanceAdmin(ctx);
27	    const body = await ctx.json();
28	    const patch = patchInstanceGeneralSettingsSchema.parse(body);
29	    const updated = await svc.updateGeneral(patch);
30	
31	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
32	    const actorId = ctx.actor!.type === "agent"
33	      ? (ctx.actor!.agentId ?? "unknown-agent")
34	      : (ctx.actor!.userId ?? "board");
35	    const companyIds = await svc.listCompanyIds();
36	    await Promise.all(
37	      companyIds.map((companyId) =>
38	        logActivity(db, {
39	          companyId,
40	          actorType,
41	          actorId,
42	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
43	          runId: ctx.actor?.runId ?? null,
44	          action: "instance.settings.general_updated",
45	          entityType: "instance_settings",
46	          entityId: updated.id,
47	          details: {
48	            general: updated.general,
49	            changedKeys: Object.keys(patch).sort(),
50	          },
51	        }),
52	      ),
53	    );
54	    return Response.json(updated.general);
55	  };
56	
57	  // server/src/routes/instance-settings.ts:65
58	  const getExperimentalSettings: Handler = async (ctx) => {
59	    assertBoardOrgAccess(ctx);
60	    return Response.json(await svc.getExperimental());
61	  };
62	
63	  // server/src/routes/instance-settings.ts:72
64	  const patchExperimentalSettings: Handler = async (ctx) => {
65	    assertInstanceAdmin(ctx);
66	    const body = await ctx.json();
67	    const patch = patchInstanceExperimentalSettingsSchema.parse(body);
68	    const updated = await svc.updateExperimental(patch);
69	
70	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
71	    const actorId = ctx.actor!.type === "agent"
72	      ? (ctx.actor!.agentId ?? "unknown-agent")
73	      : (ctx.actor!.userId ?? "board");
74	    const companyIds = await svc.listCompanyIds();
75	    await Promise.all(
76	      companyIds.map((companyId) =>
77	        logActivity(db, {
78	          companyId,
79	          actorType,
80	          actorId,
81	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
82	          runId: ctx.actor?.runId ?? null,
83	          action: "instance.settings.experimental_updated",
84	          entityType: "instance_settings",
85	          entityId: updated.id,
86	          details: {
87	            experimental: updated.experimental,
88	            changedKeys: Object.keys(patch).sort(),
89	          },
90	        }),
91	      ),
92	    );
93	    return Response.json(updated.experimental);
94	  };
95	
96	  // server/src/routes/instance-settings.ts:103
97	  const previewIssueGraphLivenessAutoRecovery: Handler = async (ctx) => {
98	    assertInstanceAdmin(ctx);
99	    const body = await ctx.json();
100	    const parsed = issueGraphLivenessAutoRecoveryRequestSchema.parse(body);
101	    return Response.json(await heartbeat.buildIssueGraphLivenessAutoRecoveryPreview({
102	      lookbackHours: parsed.lookbackHours,
103	    }));
104	  };
105	
106	  // server/src/routes/instance-settings.ts:113
107	  const runIssueGraphLivenessAutoRecovery: Handler = async (ctx) => {
108	    assertInstanceAdmin(ctx);
109	    const body = await ctx.json();
110	    const parsed = issueGraphLivenessAutoRecoveryRequestSchema.parse(body);
111	
112	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
113	    const actorId = ctx.actor!.type === "agent"
114	      ? (ctx.actor!.agentId ?? "unknown-agent")
115	      : (ctx.actor!.userId ?? "board");
116	    const result = await heartbeat.reconcileIssueGraphLiveness({
117	      runId: null,
118	      force: true,
119	      lookbackHours: parsed.lookbackHours,
120	    });
121	    const companyIds = await svc.listCompanyIds();
122	    await Promise.all(
123	      companyIds.map((companyId) =>
124	        logActivity(db, {
125	          companyId,
126	          actorType,
127	          actorId,
128	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
129	          runId: ctx.actor?.runId ?? null,
130	          action: "instance.settings.issue_graph_liveness_auto_recovery_run",
131	          entityType: "instance_settings",
132	          entityId: "default",
133	          details: {
134	            lookbackHours: result.lookbackHours,
135	            escalationsCreated: result.escalationsCreated,
136	            existingEscalations: result.existingEscalations,
137	            skippedOutsideLookback: result.skippedOutsideLookback,
138	            escalationIssueIds: result.escalationIssueIds,
139	          },
140	        }),
141	      ),
142	    );
143	    return Response.json(result);
144	  };
145	
146	  return {
147	    getGeneralSettings,
148	    patchGeneralSettings,
149	    getExperimentalSettings,
150	    patchExperimentalSettings,
151	    previewIssueGraphLivenessAutoRecovery,
152	    runIssueGraphLivenessAutoRecovery,
153	  };
154	}
155	
156	export function instanceSettingsRoutes(db: Db) {
157	  const router = Router();
158	  const {
159	    getGeneralSettings,
160	    patchGeneralSettings,
161	    getExperimentalSettings,
162	    patchExperimentalSettings,
163	    previewIssueGraphLivenessAutoRecovery,
164	    runIssueGraphLivenessAutoRecovery,
165	  } = buildHandlers(db);
166	
167	  const storageSentinel = new Proxy({} as StorageService, {
168	    get(_target, prop) {
169	      throw new Error(`instanceSettings handler unexpectedly accessed storage.${String(prop)}`);
170	    },
171	  });
172	  const deps = { db, storage: storageSentinel };
173	
174	  router.get("/instance/settings/general", expressHandler(getGeneralSettings, deps));
175	  router.patch("/instance/settings/general", expressHandler(patchGeneralSettings, deps));
176	  router.get("/instance/settings/experimental", expressHandler(getExperimentalSettings, deps));
177	  router.patch("/instance/settings/experimental", expressHandler(patchExperimentalSettings, deps));
178	  router.post(
179	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/preview",
180	    expressHandler(previewIssueGraphLivenessAutoRecovery, deps),
181	  );
182	  router.post(
183	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/run",
184	    expressHandler(runIssueGraphLivenessAutoRecovery, deps),
185	  );
186	
187	  return router;
188	}
